const it=$input.first().json; if(it && it.__err){return [{json:it}];}
const structuredPrompt = $input.first().json.output.final_prompt;
return [{json:{...it, prompt: JSON.stringify(structuredPrompt), model: "veo3_fast", aspectRatio: "16:9"}}];

const it=$input.first().json; if(it && it.__err){return [{json:it}];}

// 忠实复刻 body 注入: "prompt": {{$json.prompt}} 无引号,靠 stringify 外层引号
const body = '{\n  "prompt": ' + it.prompt + ',\n  "model": "' + it.model + '",\n  "aspectRatio": "' + it.aspectRatio + '",\n  "imageUrls": ["' + (it.images&&it.images[0]?it.images[0].url:'') + '"]\n}';
let parsed=null, injOK=true; try{ parsed=JSON.parse(body); }catch(e){ injOK=false; }
return [{json:{...it, data:{taskId:"mock-task-"+it.scenario}, _veo_body_ok:injOK}}];

const it=$input.first().json; if(it && it.__err){return [{json:it}];}

if(it.veo_url){ return [{json:{...it, data:{taskId:it.data.taskId, response:{resultUrls:[it.veo_url]}}}}]; }
return [{json:{...it, data:{taskId:it.data.taskId}}}];  // 渲染未完成: 无 response

const it=$input.first().json; if(it && it.__err){return [{json:it}];}

const cap=(it.message&&it.message.content)||'';
return [{json:{...it, STATUS:"CREATE", "TITRE VIDEO": (it.output&&it.output.title)||"?", "CAPTION VIDEO": cap, "URL VIDEO FINAL": (it.data&&it.data.response&&it.data.response.resultUrls)?it.data.response.resultUrls[0]:undefined, caption_too_long: cap.length>200}}];

const it=$input.first().json;
if(it && it.__err){return [{json:it}];}  // 上游已断,忠实中止
try{
  const ref = $("Download Video from VEO3").item.json;
  const url = ref.data.response.resultUrls[0];
  return [{json:{...it, tg_video_url:url}}];
}catch(e){
  return [{json:{...it, __err:{node:"Send Video URL via Telegram",reason:"读 record-info 的 data.response.resultUrls[0] 抛错(渲染未完成即断链,无错误网): "+e.message,fatal:true}}}];
}

const all=$input.all();
const first=all.find(x=>x.json && !x.json.__err);
if(first){return [{json:{...first.json, merged_from_9:true}}];}
return [{json:all[0].json}];

const all=$input.all();
const it=all[0].json; const S=it.scenario; const checks=[];
function A(n,c){checks.push({name:n, ok:!!c});}
A("B-"+S+".场景上下文贯通(S="+S+" 非undefined)", typeof S==="string" && S.length===2);
A("B-"+S+".items: 右链行数="+all.length+" (模板 SCENARIO 双出真正含义见报告)", all.length>=1);
if(S==="S1"){ A("B-S1.终态Published", !it.__err && it.STATUS==="Published"); A("B-S1.VEO3 body注入合法", it._veo_body_ok===true); A("B-S1.成片URL已回TG", typeof it.tg_video_url==="string" && it.tg_video_url.indexOf(".mp4")>-1); A("B-S1.状态机CREATE→Published", it.STATUS==="Published"); }
if(S==="S2"){ A("B-S2.无caption仍通链(服务端降级由LLM自担)", !it.__err && it.STATUS==="Published"); }
if(S==="S3"){ A("B-S3.坑①引爆: photo[3]断链且非photo[2]节点", !!it.__err && it.__err.node==="Telegram API: Get File URL"); }
if(S==="S4"){ A("B-S4.坑②引爆: 渲染未完成→首消费点Send Video URL断链", !!it.__err && it.__err.node==="Send Video URL via Telegram"); }
if(S==="S5"){ A("B-S5.Caption超长仍直写Sheets(模板无200符闸)", it.caption_too_long===true && !it.__err); }
return [{json:{scenario:S, checks:checks, ok: checks.every(c=>c.ok)}}];
